// One row per piece, with a publish slot. Edit SLOTS to change the cadence:
// [first day after the start date, days between pieces, hour of day]
const SLOTS = {
  'Blog post': [0, 0, 9], 'Newsletter': [2, 0, 10], 'LinkedIn post': [0, 2, 8], 'X thread': [1, 0, 12],
  'X post': [2, 2, 12], 'Instagram caption': [0, 1, 18], 'Facebook post': [1, 3, 19], 'Short video': [0, 1, 17], 'Quote card': [1, 2, 20],
};
const PLATFORM = {
  'Blog post': 'Blog', 'Newsletter': 'Email', 'LinkedIn post': 'LinkedIn', 'X thread': 'X', 'X post': 'X',
  'Instagram caption': 'Instagram', 'Facebook post': 'Facebook', 'Short video': 'Reels / TikTok / Shorts', 'Quote card': 'Instagram',
};
const req = $('Read Request').first().json;
const brief = $('Write Content Brief').first().json.output;
const blog = $('Write Blog Post').first().json.output;
const pack = $('Write Social Pack').first().json.output;
const docUrl = 'https://docs.google.com/document/d/' + $input.first().json.id + '/edit';
const start = DateTime.now().startOf('day').plus({ days: Number($('Repurpose Settings').first().json.schedule_start_in_days) || 0 });

const pieces = [
  { format: 'Blog post', hook: blog.seo_title, content: blog.meta_description + '\n\nFull article: ' + docUrl, notes: docUrl },
  { format: 'Newsletter', hook: pack.newsletter.subject, content: pack.newsletter.body },
  ...pack.linkedin_posts.map(p => ({ format: 'LinkedIn post', hook: p.hook, content: p.text })),
  { format: 'X thread', hook: pack.x_thread[0] || '', content: pack.x_thread.map((t, i) => (i + 1) + '/ ' + t).join('\n\n') },
  ...pack.x_posts.map(t => ({ format: 'X post', hook: t.slice(0, 80), content: t })),
  ...pack.instagram_captions.map(c => ({ format: 'Instagram caption', hook: c.caption.split('\n')[0].slice(0, 100), content: c.caption, hashtags: c.hashtags.map(h => '#' + h.replace(/^#/, '')).join(' ') })),
  ...pack.facebook_posts.map(t => ({ format: 'Facebook post', hook: t.split('\n')[0].slice(0, 100), content: t })),
  ...pack.short_videos.map(v => ({ format: 'Short video', hook: v.hook, content: 'Hook: ' + v.hook + '\nBeats:\n- ' + v.beats.join('\n- ') + '\nOn-screen text: ' + v.on_screen_text + '\nCaption: ' + v.caption + '\nClip: "' + v.source_quote + '"' })),
  ...pack.quote_cards.map(q => ({ format: 'Quote card', hook: q, content: q })),
];
const seen = {};
return pieces.map((p, i) => {
  const [first, every, hour] = SLOTS[p.format];
  const n = (seen[p.format] = (seen[p.format] ?? -1) + 1);
  const when = start.plus({ days: first + n * every }).set({ hour, minute: 0 });
  return { json: {
    'Item ID': req.pack_id + '-' + String(i + 1).padStart(2, '0'),
    'Pack ID': req.pack_id,
    'Created At': DateTime.now().toISO(),
    'Source': req.source_url || 'pasted transcript',
    'Source Title': brief.title,
    'Platform': PLATFORM[p.format],
    'Format': p.format,
    'Hook': p.hook,
    'Content': String(p.content).slice(0, 45000),
    'Hashtags': p.hashtags || '',
    'Scheduled For': when.toISO(),
    'Status': 'Draft',
    'Post URL': '',
    'Notes': p.notes || '',
  } };
});

