// LinkedIn posts that are approved and due, plus (once a day) a reminder for the manual platforms.
const cfg = $('Publishing Settings').first().json;
const now = DateTime.now();
const rows = $input.all().map(i => i.json).filter(r => r['Item ID'] && r.Status === 'Approved');
const due = r => r['Scheduled For'] && DateTime.fromISO(r['Scheduled For']) <= now;
const out = rows.filter(r => r.Platform === 'LinkedIn' && due(r) && !r['Post URL']).map(row => ({ action: 'linkedin', row }));
if (now.hour === Number(cfg.reminder_hour)) {
  const today = rows.filter(r => r.Platform !== 'LinkedIn' && r['Scheduled For'] && DateTime.fromISO(r['Scheduled For']).hasSame(now, 'day'));
  if (today.length) out.push({ action: 'reminder', rows: today });
}
return out.map(json => ({ json }));

